window.TXB=window.TXB||{};TXB["alab/Pro"]={"1:1":"هذه هي أمثال سليمان بن داود ملك إسرائيل،","1:2":"لتعليم الحكمة والفهم، وإدراك معاني الْأقوال المأثورة.","1:3":"وللحث على تقبل التأديب الفطن، والبر والعدل والاستقامة.","1:4":"فيحرز البسطاء فطنة، والأحداث علما وبصيرة.","1:5":"يستمع إليها الحكيم فيزداد حكمة، ويكتسب الفهيم مهارة،","1:6":"في فهم المثل والمعنى البليغ وأقوال الحكماء المأثورة وأحاجيهم.","1:7":"فإن مخافة الرب هي رأس المعرفة، أما الحمقى فيستهينون بالحكمة والتأديب.","1:8":"استمع ياابني إلى توجيه أبيك ولا تتنكر لتعليم أمك.","1:9":"فإنهما إكليل نعمة يتوج رأسك، وقلائد تطوق عنقك.","1:10":"ياابني إن استغواك الخطاة فلا تقبل.","1:11":"إن قالوا: «تعال معنا لنتربص بالناس حتى نسفك دماء أو نكمن للبريء ونقتله لغير علة.","1:12":"أو قالوا لك: تعال لنبتلعهم أحياء كما تبتلعهم الهاوية وأصحاء كالهابطين في حفرة الموت","1:13":"فنغنم كل نفيس ونملأ بيوتنا بالأسلاب.","1:14":"اربط مصيرك بمصيرنا، ولنتقاسم أسلابنا بالتساوي».","1:15":"إن قالوا لك هكذا فلا تسلك ياابني في طريقهم، واكفف قدمك عن سبيلهم.","1:16":"لأن أرجلهم تسعى حثيثا إلى الشر، وتسرع إلى سفك الدماء.","1:17":"فإنه عبثا تنصب الشبكة على مرأى الطير.","1:18":"إنما هم يتربصون لسفك دم أنفسهم، ويكمنون لإهدار حياتهم.","1:19":"هذا هو مصير كل من يثرى ظلما، فإن الثراء الحرام يذهب بحياة قانيه.","1:20":"تنادي الحكمة في الخارج؛ وفي الأسواق ترفع صوتها.","1:21":"عند مفترقات الطرق المزدحمة تهتف، وفي مداخل بوابات المدينة تردد أقوالها:","1:22":"«إلى متى أيها الجهال تظلون مولعين بالسذاجة، والساخرون تسرون بالسخرية، والحمقى بكراهية المعرفة؟","1:23":"إن رجعتم عند توبيخي وتبتم، أسكب عليكم روحي وأعلمكم كلماتي.","1:24":"ولكن لأنكم أبيتم دعوتي، ورفضتم يدي الممدودة إليكم،","1:25":"وتجاهلتم كل نصائحي ولم تقبلوا توبيخي،","1:26":"فأنا أيضا أسخر عند مصابكم، وأشمت عند حلول بليتكم.","1:27":"عندما تجتاحكم البلية كالعاصفة، وتحل بكم الكارثة كالزوبعة، عندما يعتريكم ضيق وشدة،","1:28":"حينئذ يستغيثون بي فلا أستجيب، ويلتمسونني فلا يجدونني.","1:29":"لأنهم كرهوا المعرفة ولم يؤثروا مخافة الرب،","1:30":"وتنكروا لكل مشورتي، واستخفوا بتوبيخي.","1:31":"لذلك يأكلون ثمار أعمالهم المرة، ويشبعون من عواقب مؤامراتهم","1:32":"لأن ضلال الحمقى يقتلهم، وتر ف الجهال يهلكهم.","1:33":"أما المستمع لي فيسكن آمنا مطمئنا لا يصيبه خوف من الشر».","2:1":"ياابني إن قبلت كلامي، وادخرت وصاياي في قلبك،","2:2":"وأرهفت أذنك إلى الحكمة، وأملت قلبك نحو الفهم،","2:3":"وإن نشدت الفطنة، وهتفت داعيا الفهم.","2:4":"إن التمسته كما تلتمس الفضة، وبحثت عنه كما يبحث عن الكنوز الدفينة،","2:5":"عندئذ تدرك مخافة الرب وتعثر على معرفة الله،","2:6":"لأن الرب يهب الحكمة، ومن فمه تتدفق المعرفة والفهم.","2:7":"يذخر للمستقيمين فطنة، وهو ترس للسالكين بالكمال.","2:8":"يرعى سبل العدل، ويحافظ على طريق أتقيائه.","2:9":"حينئذ تدرك العدل والحق والاستقامة، وكل سبيل صالح.","2:10":"إن استقرت الحكمة في قلبك واستلذت نفسك المعرفة،","2:11":"يرعاك التعقل، ويحرسك الفهم.","2:12":"إنقاذا لك من طريق الشر ومن الناطقين بالأكاذيب.","2:13":"من الذين يبتعدون عن سواء السبيل ويسلكون في طرق الظلمة،","2:14":"الذين يفرحون بارتكاب المساويء، ويبتهجون بنفاق الشر،","2:15":"من ذوي المسالك الملتوية والسبل المعوجة.","2:16":"وإنقاذا لك من المرأة الغريبة المخاتلة التي تتملقك بكلامها،","2:17":"التي نبذت شريك صباها وتناست عهد إلهها.","2:18":"لأن بيتها يغوص عميقا إلى الموت، وسبلها تفضي إلى عالم الأرواح.","2:19":"كل من يدخل إليها لا يرجع ولا يبلغ سبل الحياة.","2:20":"لهذا سر في طريق الأخيار، واحفظ سبيل الأبرار،","2:21":"لأن المستقيمين يسكنون الأرض، والكاملين يمكثون دائما فيها.","2:22":"أما الأشرار فينقرضون من الأرض، والغادرون يستأصلون منها.","3:1":"ياابني لا تنس تعاليمي، وليراع قلبك وصاياي.","3:2":"لأنها تمد في أيام عمرك، وتزيدك سني حياة وسلاما.","3:3":"لا تدع الرحمة والأمانة يتخليان عنك، بل تقلدهما في عنقك، واكتبهما على صفحة قلبك،","3:4":"فتحظى بالرضى وحسن السيرة في عيون الله والناس.","3:5":"اتكل على الرب من كل قلبك، وعلى فطنتك لا تعتمد.","3:6":"اعرف الرب في كل طرقك وهو يقوم سبلك.","3:7":"لا تكن حكيما في عيني نفسك بل اتق الرب وحد عن الشر،","3:8":"فيتمتع جسدك بالصحة، وعظامك بالارتواء.","3:9":"أكرم الرب من مالك، ومن أوائل غلات محاصيلك.","3:10":"فتمتليء أهراؤك وفرة، وتفيض معاصرك خمرا.","3:11":"ياابني لا تحتقر تأديب الرب ولا تكره توبيخه،","3:12":"لأن الرب يؤدب من يحبه، ويسر به كما يسر أب بابنه.","3:13":"طوبى للإنسان الذي عثر على الحكمة وللرجل الذي أحرز فهما،","3:14":"لأن مكاسبها أفضل من مكاسب الفضة، وأرباحها خير من أرباح الذهب الخالص.","3:15":"هي أثمن من الجواهر، وكل نفائسك لا تعادلها.","3:16":"في يمينها حياة مديدة وفي يسارها غنى وجاه.","3:17":"طرقها طرق نعم، ودروبها دروب سلام.","3:18":"هي شجرة حياة لمن يتشبث بها، وطوبى لمن يتمسك بها.","3:19":"بالحكمة أسس الرب الأرض، وبالفطنة ثبت السماوات في مواضعها.","3:20":"بعلمه تفجرت اللجج، وقطر السحاب ندى.","3:21":"فلا تبرح ياابني هذه من أمام عينيك واعمل بالرأي الصائب والتدبير.","3:22":"فيكون هذان حياة لنفسك وقلادة تجمل عنقك.","3:23":"فتسلك آنئذ في طريقك آمنا ولا تتعثر قدمك.","3:24":"إذا اضطجعت لا يعتريك خوف، بل ترقد متمتعا بالنوم اللذيذ.","3:25":"لا تفزع من بلية مباغتة، ولا مما يجري على الأشرار من خراب إذا حل بهم.","3:26":"لأن الرب يكون معتمدك، ويصون رجلك من الشرك.","3:27":"لا تحجب الإحسان عن أهله كلما كان في وسعك أن تقوم به.","3:28":"لا تقل لجارك: «اذهب الآن، ثم عد ثانية. غدا أعطيك ما تطلب»، طالما لديك ما يطلب.","3:29":"لا تتآمر بالشر على جارك المقيم مطمئنا إلى جوارك.","3:30":"لا تخاصم أحدا من غير علة طالما لم يؤذك.","3:31":"لا تغر من الظالم ولا تختر طرقه.","3:32":"لأن الملتوي رجس لدى الرب، أما المستقيمون فهم أهل ثقته.","3:33":"لعنة الرب تنصب على بيت الشرير، لكنه يبارك مسكن الصديق.","3:34":"يسخر من المستكبرين الساخرين، ويغدق رضاه على المتواضعين","3:35":"يرث الحكماء كرامة، أما الحمقى فيرتدون العار.","4:1":"استمعوا أيها البنون إلى إرشاد الأب، وأصغوا لتكتسبوا الفطنة،","4:2":"فإني أقدم لكم تعليما صالحا، فلا تهملوا شريعتي.","4:3":"عندما كنت ابنا لأبي، غضا وحيدا لأمي،","4:4":"قال لي: «ادخر في قلبك كلامي، واحفظ وصاياي فتحيا.","4:5":"لا تنس ولا تعرض عن أقوال فمي، بل تلقن الحكمة واقتن الفطنة.","4:6":"لا تنبذها فتحفظك. أحببها فتصونك.","4:7":"بداية الحكمة أن تكسب حكمة، واقتن الفطنة ولو بذلت كل ما تملك.","4:8":"مجدها فتمجدك، اعتنقها فتكرمك.","4:9":"تتوج رأسك بإكليل جمال، وتنعم عليك بتاج بهاء».","4:10":"استمع ياابني وتقبل أقوالي، لتطول سنو حياتك.","4:11":"قد أرشدتك إلى طريق الحكمة، وهديتك في مناهج الاستقامة.","4:12":"عندما تمشي لا تضيق خطواتك، وحين تركض لا تتعثر.","4:13":"تمسك بالإرشاد ولا تطرحه. صنه لأنه حياتك.","4:14":"لا تدخل في سبيل الأشرار ولا تنهج نهجهم.","4:15":"ابتعد عنه ولا تعبر به. حد عنه ولا تجتز فيه.","4:16":"فإنهم لا يركنون إلى النوم ما لم يسيئوا، ويفارقهم النعاس ما لم يعثروا أحدا.","4:17":"لأنهم يأكلون خبز الشر ويشربون خمر الظلم.","4:18":"أما سبيل الأبرار فكنور متلأليء يتزايد إشراقه إلى أن يكتمل النهار،","4:19":"وطريق الأشرار كالظلمة الداجية لا يدركون ما يعثرون به.","4:20":"ياابني أصغ إلى كلمات حكمتي، وأرهف أذنك إلى أقوالي.","4:21":"لتظل ماثلة أمام عينيك واحتفظ بها في داخل قلبك،","4:22":"لأنها حياة لمن يعثر عليها، وعافية لكل جسده.","4:23":"فوق كل حرص احفظ قلبك لأن منه تنبثق الحياة.","4:24":"انزع من فمك كل قول ملتو، وأبعد عن شفتيك خبيث الكلام.","4:25":"حدق باستقامة أمامك، ووجه أنظارك إلى قدامك.","4:26":"تبين موقع قدمك، فتضحى جميع طرقك ثابتة.","4:27":"لا تحد يمينا أو شمالا، وأبعد رجلك عن مسالك الشر.","5:1":"ياابني أصغ إلى حكمتي، وأرهف أذنك إلى قول فطنتي.","5:2":"لكي تدخر الفطنة، وترعى شفتاك العلم.","5:3":"لأن شفتي المرأة العاهرة تقطران شهدا، وحديثها أكثر نعومة من الزيت،","5:4":"لكن عاقبتها مرة كالعلقم، حادة كسيف ذي حدين.","5:5":"تنحدر قدماها إلى الموت، وخطواتها تتشبث بالهاوية.","5:6":"لا تتأمل طريق الحياة؛ تترنح خطواتها وهي لا تدرك ذلك.","5:7":"والآن أصغوا إلي أيها البنون، ولا تهجروا كلمات فمي.","5:8":"أبعد طريقك عنها، ولا تقترب من باب بيتها،","5:9":"لئلا تعطي كرامتك للآخرين، وسني عمرك لمن لا يرحم،","5:10":"فيستهلك الغرباء ثروتك حتى الشبع، وتضحى غلة أتعابك في بيت الأجنبي.","5:11":"فتنوح في أواخر حياتك، عند فناء لحمك وجسدك، لإصابتك بأمراض معدية،","5:12":"وتقول: «كيف مقت التأديب، واستخف قلبي بالتوبيخ،","5:13":"فلم أصغ إلى توجيه مرشدي، ولا استمعت إلى معلمي.","5:14":"حتى كدت أتلف في وسط الجمهور والجماعة».","5:15":"اشرب ماء من جبك، ومياها جارية من بئرك.","5:16":"أينبغي على ينابيعك أن تفيض إلى الخارج كأنهار مياه في الشوارع؟","5:17":"ليكن أولادك لك وحدك، لا نصيب للغرباء معك فيهم.","5:18":"ليكن ينبوع عفتك مباركا، واغتبط بامرأة شبابك،","5:19":"فتكون كالظبية المحبوبة والوعلة البهية، فترتوي من فيض فتنتها، وتظل دائما أسير حبها.","5:20":"لماذا تولع ياابني بالمرأة العاهرة أو تحتضن الغريبة؟","5:21":"فإن تصرفات الإنسان مكشوفة أمام عيني الرب، وهو يبصر جميع طرقه.","5:22":"آثام المنافق تتصيده، ويعلق بحبال خطيئته.","5:23":"يموت افتقارا إلى التأديب، وبحمقه يتشرد.","6:1":"ياابني إن ضمنت أحدا، وإن أخذت على نفسك عهدا للغريب؛","6:2":"إن وقعت في فخ أقوال فمك، وعلقت بكلام شفتيك،","6:3":"فافعل هذا ياابني ونج نفسك، لأنك أصبحت تحت رحمة صاحبك: اذهب تذلل إليه","6:4":"وألح عليه. لا يغلب عليك النوم، ولا على أجفانك النعاس،","6:5":"نج نفسك كالظبي من يد الصياد أو كالعصفور من قبضة القناص.","6:6":"اذهب إلى النملة أيها الكسول، تمعن في طرقها وكن حكيما،","6:7":"فمع أنها من غير قائد أو مدبر أو حاكم،","6:8":"إلا أنها تخزن طعامها في الصيف، وتجمع مؤونتها في موسم الحصاد.","6:9":"فإلى متى تظل راقدا أيها الكسول؟ متى تهب من نومك؟","6:10":"فإن بعض النوم، ثم بعض الرقاد، وطي اليدين للهجوع،","6:11":"تجعل الفقر يقبل عليك كقاطع طريق، والفاقة كغاز مسلح.","6:12":"الرجل المغتاب، الرجل الأثيم هو من يسعى بنميمة الفم الكاذبة،","6:13":"ويغمز بعينيه، ويشير برجليه، ويكشف عن نواياه بحركات أصابعه.","6:14":"يخترع الشر بقلب مخادع، ويثير الخصومات دائما.","6:15":"لذلك تغشاه البلايا فجأة، وفي لحظة يتحطم ويستعصي شفاؤه.","6:16":"ستة أمور يمقتها الرب، وسبعة مكروهة لديه:","6:17":"عينان متعجرفتان، ولسان كاذب، ويدان تسفكان دما بريئا.","6:18":"وقلب يتآمر بالشر، وقدمان تسرعان بصاحبهما لارتكاب الإثم،","6:19":"وشاهد زور ينفث كذبا، ورجل يزرع خصومات بين الإخوة.","6:20":"ياابني احفظ وصايا أبيك ولا تتجاهل شريعة أمك.","6:21":"اعقدها دائما على قلبك، وتقلد بها في عنقك،","6:22":"فتهديك كلما مشيت، وترعاك كلما نمت، وتناجيك عندما تستيقظ.","6:23":"فالوصية مصباح والشريعة نور، والتوبيخ في سبيل التأديب هو طريق حياة،","6:24":"لكي تقيك من المرأة الشريرة ومن لسان العاهرة المعسول.","6:25":"لا تشته جمالها في قلبك ولا تأسر لبك بأهدابها.","6:26":"لأنه بسبب المرأة العاهرة يفتقر الإنسان إلى رغيف خبز، والزانية المتزوجة تقتنص بأشراكها النفس الكريمة.","6:27":"أيمكن للمرء أن يضع نارا في حضنه ولا تحترق ثيابه؟","6:28":"أو أن يمشي على جمر ولا تكتوي قدماه؟","6:29":"هذا ما يصيب كل من يزني بامرأة غيره؛ حتما يحل به العقاب.","6:30":"ومع أن الناس قد لا تحتقر لصا إذا سرق ليشبع بطنه وهو جائع،","6:31":"لكن إذا قبض عليه متلبسا بالجريمة يعوض سبعة أضعاف، حتى ولو كلفه ذلك كل ما يقتنيه.","6:32":"أما الزاني فيفتقر إلى الإدراك السليم، وكل من يرتكب الزنى يدمر نفسه،","6:33":"إذ يتعرض للضرب والهوان، وعاره لا يمحى أبدا.","6:34":"لأن الغيرة تفجر غضب الرجل فلا يرحم عندما يقدم على الانتقام.","6:35":"لا يقبل الفدية، ويأبى الاسترضاء مهما أكثرت الرشوة.","7:1":"ياابني احفظ أقوالي واذخر وصاياي معك.","7:2":"أطع وصاياي فتحيا، وصن شريعتي كحدقة عينك.","7:3":"اعصبها على أصابعك، واكتبها على صفحات قلبك.","7:4":"قل للحكمة: أنت أختي، وللفطنة: أنت قريبتي.","7:5":"فهما تحفظانك من المرأة العاهرة، والزوجة الفاسقة التي تتملق بكلامها.","7:6":"فإني أشرفت من كوة بيتي، وأطللت من خلال نافذتي،","7:7":"فشاهدت بين البنين الحمقى شابا مجردا من الفهم،","7:8":"يجتاز الطريق صوب المنعطف، باتجاه الشارع المفضي إلى بيتها.","7:9":"عند الغسق في المساء تحت جنح الليل والظلمة.","7:10":"فإذا بامرأة تستقبله في زي زانية وقلب مخادع.","7:11":"صخابة وجامحة لا تستقر قدماها في بيتها.","7:12":"تر اها تارة في الخارج، وطورا في ساحات الأسواق، تكمن عند كل منعطف.","7:13":"فأمسكته وقبلته وقالت له بوجه وقح:","7:14":"«كان علي أن أقدم ذبائح سلام، فأوفيت اليوم نذوري.","7:15":"وقد خرجت لاستقبالك، بعد أن بحثت بشوق عنك حتى وجدتك.","7:16":"قد فرشت سريري بأغطية كتانية موشاة من مصر،","7:17":"وعطرت فراشي بطيب المر والقرفة.","7:18":"فتعال لنرتوي من الحب حتى الصباح، ونتلذذ بمتع الغرام.","7:19":"فإن زوجي ليس في البيت، قد مضى في رحلة بعيدة.","7:20":"وأخذ معه صرة مكتنزة بالمال، ولن يعود إلا عند اكتمال البدر».","7:21":"فأغوته بكثرة أفانين كلامها، ورنحته بتملق شفتيها.","7:22":"فمضى على التو في إثرها، كثور مسوق إلى الذبح، أو أيل وقع في فخ.","7:23":"إلى أن ينفذ سهم في كبده، ويكون كعصفور مندفع إلى شرك، لا يدري أنه قد نصب للقضاء عليه.","7:24":"والآن أصغوا إلي أيها الأبناء، وأرهفوا آذانكم إلى أقوال فمي:","7:25":"لا تجنح قلوبكم نحو طرقها، ولا تحوم في دروبها.","7:26":"فما أكثر الذين طرحتهم مثخنين بالجراح، وجميع صرعاها أقوياء.","7:27":"إن بيتها هو طريق الهاوية المؤدي إلى مخادع الموت.","8:1":"ألا تنادي الحكمة؟ ألا يرتفع صوت الفطنة هاتفا؟","8:2":"إنها تقف على المرتفعات، في محاذاة الطريق، وعند ملتقى الشوارع.","8:3":"إلى جوار أبواب المدينة وفي مدخل الثغر، تنتصب مجاهرة قائلة:","8:4":"إياكم أدعو أيها الناس وأرفع صوتي بالنداء إلى كل بني البشر.","8:5":"أيها الحمقى، تعلموا الفطنة، وأيها الأغبياء اكتسبوا فهما.","8:6":"أنصتوا لأنني سأنطق بأقوال أثيرة، وأفتح شفتي بكلام قويم.","8:7":"لأن فمي يتكلم بالصدق، وشفتي تمقتان الإثم.","8:8":"كل أقوال فمي عادلة خالية من كل التواء واعوجاج.","8:9":"قويمة لدى الفهيم، ومستقيمة للذين أدركوا المعرفة.","8:10":"اختر إرشادي عوض الفضة، والمعرفة بدل الذهب الخالص.","8:11":"لأن الحكمة أفضل من اللآليء، وكل مشتهياتك لا تعادلها.","8:12":"أنا الحكمة أسكن التعقل، وأملك المعرفة والتدبير.","8:13":"مخافة الرب كراهة الشر. أنا قد أبغضت الكبرياء والغطرسة وطريق السوء وفم المكر.","8:14":"لي المشورة والرأي الصائب، لي الفطنة والقوة.","8:15":"بمعونتي يحكم الملوك، ويشترع الحكام ما هو عدل.","8:16":"بمعونتي يسود الرؤساء والعظماء وكل قضاة الأرض.","8:17":"أحب من يحبونني، ومن يجد في البحث عني يعثر علي.","8:18":"لدي الثراء والمجد والغنى الدائم والصلاح.","8:19":"ثمري أفضل من الذهب الخالص، وغلتي خير من الفضة المنتقاة.","8:20":"أمشي في طريق البر، وفي سبل العدل أسير.","8:21":"لكي أورث محبي غنى، وأملأ خزائنهم كنوزا.","8:22":"اقتناني الرب منذ بدء خلقه، من قبل الشروع في أعماله القديمة.","8:23":"منذ الأزل أنا هو، منذ البدء قبل أن توجد الأرض.","8:24":"ولدت من قبل أن تتكون اللجج والينابيع الغزيرة المياه.","8:25":"ولدت من قبل أن تقررت الجبال والتلال.","8:26":"إذ لم يكن قد خلق الأرض بعد، ولا البراري ولا بداية أتربة المسكونة.","8:27":"وعندما ثبت الرب السماء، وحين رسم دائرة الأفق حول وجه الغمر، كنت هناك.","8:28":"عندما ثبت السحب في العلاء، ورسخ ينابيع اللجج.","8:29":"عندما قرر للبحر تخوما لا تتجاوزها مياهه متعدية على أمر الرب، وحين رسم أسس الأرض،","8:30":"كنت عنده صانعا مبدعا، وكنت كل يوم لذته، أفيض بهجة دائما أمامه.","8:31":"مغتبطة بعالمه المسكون، ومسراتي مع بني آدم.","8:32":"والآن أصغوا إلي أيها الأبناء، إذ طوبى لمن يمارسون طرقي.","8:33":"استمعوا إلى إرشادي، وكونوا حكماء ولا تتجاهلوه.","8:34":"طوبى للإنسان الذي يستمع إلي، الحريص على السهر عند أبوابي، حارسا قوائم مصاريعي،","8:35":"لأن من يجدني يجد حياة، ويحوز على مرضاة الرب.","8:36":"ومن يضل عني يؤذي نفسه، ومن يبغضني يحب الموت.","9:1":"الحكمة شيدت بيتها، ونحتت أعمدتها السبعة","9:2":"ذبحت ذبائحها، ومزجت خمرها، وأعدت مأدبتها.","9:3":"أرسلت جواريها لينادين من أعلى مشارف المدينة قائلات:","9:4":"«كل من هو ساذج فليمل إلى هنا». وتدعو كل غبي قائلة:","9:5":"«تعالوا كلوا من خبزي واشربوا من الخمر التي مزجت.","9:6":"انبذوا الجهالة فتحيوا، واسلكوا سبيل الفهم».","9:7":"من يسع لتقويم الساخر يلحقه الهوان، ومن يوبخ الشرير يعده عيبه.","9:8":"لا تقرع الساخر لئلا يبغضك، ووبخ الحكيم فيحبك.","9:9":"اسد الإرشاد إلى الحكيم فيضحى أوفر حكمة، علم الصديق فيزداد معرفة.","9:10":"أول الحكمة تقوى الرب، ومعرفة القدوس عين الفطنة.","9:11":"إذ بي تكثر أيامك، وتطول سنو حياتك.","9:12":"إن كنت حكيما فلنفسك، وإن كنت ساخرا فأنت الجاني على ذاتك.","9:13":"المرأة الجاهلة صخابة حمقاء، مجردة من كل معرفة.","9:14":"تجلس عند باب بيتها، على مقعد في أعلى مشارف المدينة،","9:15":"تنادي العابرين بها، السالكين في طرقهم باستقامة قائلة:","9:16":"«كل من هو جاهل فليمل إلى هنا». وتقول لكل غبي:","9:17":"«المياه المسروقة عذبة، والخبز المأكول خفية شهي».","9:18":"ولكنه لا يدري أن أشباح الموتى هناك، وأن ضيوفها مطروحون في أعماق الهاوية.","10:1":"هذه أمثال سليمان: الابن الحكيم مسرة لأبيه، والابن الجاهل حسرة لأمه.","10:2":"كنوز المال الحرام لا تجدي، ولكن الحق ينجي من الموت.","10:3":"لا يجيع الرب نفس الصديق، أما هوى الأشرار فينبذه.","10:4":"العامل بيد مسترخية يفتقر، أما اليد الكادحة فتغني.","10:5":"من يجمع في الصيف مؤونته هو ابن عاقل، أما من ينام في موسم الحصاد فهو ابن مخز.","10:6":"تتوج البركات رأس الصديق، أما فم الأشرار فيطغى عليه الظلم.","10:7":"ذكر الصديق بركة، واسم الأشرار يعتريه البلى.","10:8":"الحكيم القلب يتقبل الوصايا، والمتبجح الشفتين مصيره الخراب.","10:9":"من يسلك باستقامة يسير مطمئنا، وذو الطرق المنحرفة يفتضح.","10:10":"من يغمز بعينه مكرا يولد غما. والموبخ بجرأة يصنع سلاما.","10:11":"فم الصديق ينبع بكلام الحياة، أما فم الشرير فيطغى عليه الظلم.","10:12":"البغضاء تثير الخصومات، والمحبة تستر جميع الذنوب.","10:13":"في شفتي العاقل تكمن حكمة أما العصا فمن نصيب ظهر الأحمق.","10:14":"الحكماء يذخرون المعرفة، أما فم الغبي فيجلب الدمار.","10:15":"ثروة الغني قلعته الحصينة، وفي فقر المساكين هلاكهم.","10:16":"عمل الصديق يفضي إلى الحياة، وربح الشرير يؤدي إلى الخطيئة.","10:17":"من يعمل بمقتضى التعليم يسير في درب الحياة، ومن يرفض التأديب يضل.","10:18":"من يضمر البغضاء تنطق شفتاه بالكذب، ومن جاهر بالمذمة فهو أحمق.","10:19":"في كثرة الكلام زلات لسان، ومن يضبط شفتيه فهو عاقل.","10:20":"كلام الصديق كالفضة المصفاة، وقلب الشرير يخلو من كل قيمة.","10:21":"كلام الصديق يفيد كثيرين، أما الحمقى فيموتون من سوء الفهم.","10:22":"في بركة الرب غنى لا تضيف إليها المشقة تعبا.","10:23":"ارتكاب الفاحشة عند الجاهل كاللعب، أما حسن التصرف فمسرة للحكيم.","10:24":"ما يخشى منه الشرير يقبل إليه، وشهوة الصديقين تمنح لهم.","10:25":"يتلاشى الشرير كما تتلاشى الزوبعة، أما الصديق فيخلد إلى الأبد.","10:26":"الكسول لمن أرسله كالخل للأسنان أو كالدخان للعينين.","10:27":"تقوى الرب تطيل أيام الحياة، أما سنو الشرير فتقصر.","10:28":"البهجة هي أمل الصديق، ورجاء الأشرار مآله الفناء.","10:29":"طريق الرب هو ملاذ للمستقيمين، ودمار لفاعلي الإثم.","10:30":"لا يزحزح الصديق أبدا، أما الأشرار فلا يسكنون الأرض.","10:31":"من فم الصديق تفيض الحكمة، واللسان المخاتل يقطع.","10:32":"شفتا الصديق تدركان ما هو حق، فتنطقان به، وفم الشرير لا يتكلم إلا بالباطل.","11:1":"الميزان المغشوش رجس لدى الرب، والمكيال الوافي يحوز رضاه.","11:2":"حينما تقبل الكبرياء يقبل معها الهوان، أما الحكمة فتأتي مع المتواضعين.","11:3":"كمال المستقيمين يهديهم، واعوجاج الغادرين يدمرهم.","11:4":"لا يجدي الغنى في يوم قضاء الرب، أما البر فينجي من الموت.","11:5":"بر الكامل يقوم طريقه، أما الشرير فيسقط في حفرة شره.","11:6":"بر المستقيم ينجيه، والغادرون يؤخذون بفجورهم.","11:7":"إذا مات الشرير يفنى رجاؤه، وأمل الأثمة يبيد.","11:8":"الصديق ينجو من الضيق، وفي مكانه يحل الشرير.","11:9":"يدمر المنافق صاحبه بأقواله، وينجو الصديق بالمعرفة.","11:10":"تتهلل المدينة لفلاح الأبرار، ويشيع هتاف البهجة لدى موت الأشرار.","11:11":"ببركة المستقيمين تتعظم المدينة، وتهدم بسبب أقوال الأشرار.","11:12":"من يحتقر جاره يفتقر إلى الإدراك السليم، وذو الفطنة يعتصم بالصمت.","11:13":"الواشي يفشي السر، والأمين النفس يكتمه.","11:14":"يسقط الشعب حيث تنعدم الهداية، وبكثرة المشيرين يتحقق الخلاص.","11:15":"من يضمن الغريب يتعرض لأشد الأذى، ومن يمقت الضامنين بصفق الأيدي يطمئن.","11:16":"المرأة الرقيقة القلب تحظى بالكرامة، والعنفاء لا يحصلون إلا على الغنى.","11:17":"الرحيم يحسن إلى نفسه، والقاسي يؤذي ذاته.","11:18":"الشرير يكسب أجرة غش زائلة، أما زارع البر فله ثواب أكيد دائم.","11:19":"المتشبث بالبر يحيا، ومن يتبع الشر يموت.","11:20":"ذوو القلوب المعوجة رجس لدى الرب، وبذوي السيرة المستقيمة مرضاته.","11:21":"الشرير لا يفلت حتما من العقاب، أما ذرية الصديقين فتنجو.","11:22":"المرأة الجميلة المجردة من الحكمة كخزامة من ذهب في أنف خنزيرة.","11:23":"بغية الصديقين الخير فقط، أما توقعات الشرير فهي في الغضب.","11:24":"قد يسخو المرء بما عنده فيزداد غنى ويبخل آخر بما عليه أن يسخو به فيفتقر.","11:25":"النفس السخية تزداد ثراء، والمروي يروى أيضا.","11:26":"يلعن الشعب محتكر الحنطة، وتحل البركة على رأس من يبيعها.","11:27":"من يسعى في الخير، يلتمس الرضى، ومن ينشد الشر يقبل إليه.","11:28":"من يتكل على غناه يسقط، أما الصديقون فيزهون كأوراق الشجر الخضراء.","11:29":"من يكدر حياة أهل بيته يرث الريح، ويصبح الأحمق خادما للحكيم.","11:30":"ثمر الصديق شجرة حياة، ورابح النفوس حكيم.","11:31":"إن كان الصديق يجازى على الأرض، فكم بالحري يكون جزاء الشرير والخاطيء.","12:1":"من يحب التأديب يحب المعرفة، ومن يمقت التأنيب غبي.","12:2":"الصالح يحظى برضى الرب، ورجل المكائد يستجلب قضاءه.","12:3":"لا يثبت الإنسان بالشر، أما أصل الصديق فلا يتزعزع.","12:4":"المرأة الفاضلة تاج لزوجها، أما جالبة الخزي فكنخر في عظامه.","12:5":"مقاصد الصديق شريفة، وتدابير الشرير غادرة.","12:6":"كلام الأشرار يتربص لسفك الدم، وأقوال المستقيمين تسعى للإنقاذ.","12:7":"مصير الأشرار الانهيار والتلاشي، أما صرح الصديقين فيثبت راسخا.","12:8":"يحمد المرء لتعقله، ويزدرى ذو القلب الملتوي.","12:9":"الحقير الكادح خير من المتعاظم المفتقر للقمة الخبز.","12:10":"الصديق يراعي نفس بهيمته، أما الشرير فأرق مراحمه تتسم بالقسوة.","12:11":"من يفلح أرضه، تكثر غلة خبزه، ومن يلاحق الأوهام فهو أحمق.","12:12":"يشتهي الشرير مناهب الإثم، أما الصديق فيزدهر.","12:13":"يقع الشرير في فخ أكاذيب لسانه، أما الصديق فيفلت من الضيق.","12:14":"من ثمر صدق أقواله يشبع الإنسان خيرا، كما ترد له ثمار أعمال يديه.","12:15":"يبدو سبيل الأحمق صالحا في عينيه، أما الحكيم فيستمع إلى المشورة.","12:16":"يبدي الأحمق غيظه في لحظة، أما العاقل فيتجاهل الإهانة.","12:17":"من ينطق بالصدق يشهد بالحق، أما شاهد الزور فيتكلم بالكذب.","12:18":"رب مهذار تنفذ كلماته كطعنات السيف، وفي أقوال فم الحكماء شفاء.","12:19":"أقوال الشفاه الصادقة تدوم إلى الأبد، أما أكاذيب لسان الزور فتنفضح في لحظة.","12:20":"يكمن الغش في قلوب مدبري الشر، أما الفرح فيملأ صدور الساعين إلى السلام.","12:21":"لا يصيب الصديق سوء، أما الأشرار فيحيق بهم الأذى.","12:22":"الشفاه الكاذبة رجس لدى الرب، ومسرته بالعاملين بالصدق.","12:23":"العاقل يحتفظ بعلمه، وقلوب الجهال تفضح ما فيها من سفاهة.","12:24":"ذو اليد المجتهدة يسود، والكسول ذو اليد المرتخية يخدم تحت الجزية.","12:25":"القلب القلق الجزع يوهن الإنسان، والكلمة الطيبة تفرحه.","12:26":"الصديق يهدي صاحبه، أما طريق الأشرار فتضله.","12:27":"المتقاعس لا يحظى بصيد، وأثمن ما لدى الإنسان هو اجتهاده.","12:28":"سبيل البر يفضي إلى الحياة، وفي طريقه خلود.","13:1":"الابن الحكيم يقبل تأديب أبيه، أما المستهزيء فلا يستمع للانتهار.","13:2":"من ثمر أقوال فمه يأكل الإنسان خيرا، وشهوة الغادرين ارتكاب الظلم.","13:3":"من ضبط لسانه صان حياته، ومن فغر شدقيه متهورا بكلامه، فمصيره الدمار.","13:4":"نفس الكسول تشتهي كثيرا ولا تحصل على شيء، أما نفس المجتهد فتغنى.","13:5":"يمقت الصديق الكذب، أما الشرير فبكثرة كذبه يخزي ويخجل.","13:6":"البر يحفظ صاحب السيرة الكاملة، ويطوح الشر بالخاطيء.","13:7":"رب فقير معدم يتظاهر بالغنى، وكثير الغنى يتظاهر بالفقر.","13:8":"يفتدي المرء نفسه بغناه، أما الفقير فلا يبالي بالتهديد.","13:9":"نور الأبرار يتلألأ بالبهجة، وسراج الأشرار ينطفيء ويظلم.","13:10":"تولد الكبرياء الخصومة، أما المشاورون فذوو حكمة.","13:11":"مال الظلم يتبدد سريعا، والمال المدخر من تعب اليد يزداد.","13:12":"الأمل المماطل يسقم القلب، والرغبة المتحققة شجرة حياة.","13:13":"من ازدرى بكلمة الله يجلب على نفسه الخراب، ومن خشي وصية الله يلقى الثواب.","13:14":"شريعة الحكيم تنعش كينبوع حياة، ومن يقبلها يتفادى أشراك الموت.","13:15":"حسن التعقل يحرز الرضى، أما سبيل الغادرين فلا يدوم.","13:16":"كل عاقل يعمل بالمعرفة أما الأحمق فيعرض حمقه.","13:17":"الرسول الشرير يوقع الناس في الأزمات، أما السفير الأمين فيصلح بين المتخاصمين.","13:18":"من يرفض التأديب يحل به الفقر والذل، ومن يتجاوب مع التوبيخ يكرم.","13:19":"الرغبة الصالحة التي تتحقق تلذ النفس، وتجنب الشر رجس لدى الحمقى.","13:20":"من يعاشر الحكماء يصبح حكيما، ورفيق الحمقى يناله الأذى.","13:21":"تلاحق البلية الخطاة، ويثاب الصديقون خيرا.","13:22":"ثروة الصالح تدوم حتى يرثها الأحفاد، أما ميراث الخاطيء فمدخر للصديق.","13:23":"قد ينتج حقل الفقير المحروث وفرة من الغلال، إنما يتلفها سوء التبصر.","13:24":"من كف عن تأديب ابنه يمقته، ومن يحب ابنه يسعى إلى تأديبه.","13:25":"يأكل الصديق حتى الشبع، أما بطن الشرير فتظل خاوية.","14:1":"حكمة المرأة تبني بيتها، وحماقتها تهدمه بيديها.","14:2":"السالك باستقامته يتقي الرب، وذو الطرق المعوجة يستخف به.","14:3":"في أقوال فم الجاهل سفاهة تخزي كبرياءه، أما شفاه الحكماء فتصونهم.","14:4":"الحظيرة الخاوية من البقر معلفها فار غ، ووفرة الغلال بقوة الثور.","14:5":"الشاهد الأمين لا يكذب، والشاهد الزور ينفث كذبا.","14:6":"عبثا يلتمس الأحمق حكمة، أما العلم فمتيسر للفطن.","14:7":"انصرف من حضرة الجاهل إذ لا علم في أقواله.","14:8":"حكمة العاقل في تبين حسن مسلكه، وغباوة الجهال في ارتكاب خدعهم.","14:9":"كل جاهل يستهزيء بالإثم، أما بين المستقيمين فيشيع رضى الله.","14:10":"القلب وحده يعرف عمق مرارة نفسه، ولا يقاسمه فرحه غريب.","14:11":"بيت الأشرار ينهار، وخباء المستقيمين يزدهر.","14:12":"رب طريق تبدو للإنسان قويمة، ولكن عاقبتها هوة الموت.","14:13":"في الضحك أيضا تطغى الكآبة على القلب، وعاقبة الفرح الغم.","14:14":"ذو القلب المرتد يجازى بمقتضى طرقه، والصالح يثاب.","14:15":"الغبي يصدق كل كلمة تقال له، والعاقل يتنبه إلى موقع خطواته.","14:16":"الحكيم يخشى الشر ويتفاداه، والجاهل يتصلف ويدعي الثقة بالنفس.","14:17":"ذو الطبع الحاد يتصرف بحمق، وذو المكائد ممقوت.","14:18":"يرث الأغبياء الحماقة، ويتوج العقلاء بالعلم.","14:19":"ينحني الأشرار في محضر الأخيار، والأثمة لدى الصديق.","14:20":"الفقير مكروه حتى عند جاره، أما محبو الغني فكثيرون.","14:21":"من يحتقر صاحبه يأثم، وطوبى لمن يرحم البائسين.","14:22":"ألا يضل مخترعو الشر؟ أما العاملون خيرا فيلاقون رحمة وصدقا.","14:23":"في كل جهد مبذول ربح، أما مجرد الكلام فيؤدي إلى الفقر.","14:24":"تاج الحكماء غنى حكمتهم، والحماقة إكليل الجهال.","14:25":"شاهد الحق ينجي النفوس، والناطق بالزور ينفث كذبا.","14:26":"في تقوى الرب ثقة شديدة؛ فيها يجد أبناؤه ملاذا.","14:27":"تقوى الرب ينبوع حياة لتفادي أشراك الموت.","14:28":"في كثرة الشعب فخر للملك، وفي فقدان الرعية دمار لمقام الأمير.","14:29":"البطيء الغضب ذو فهم كثير، أما السريع إلى السخط فيبدي حماقة.","14:30":"القلب المطمئن يهب أعضاء الجسد حياة، والحسد ينخر في العظام.","14:31":"من يجور على الفقير يهين صانعه، ومن يرحم البائس يكرم خالقه،","14:32":"يعاقب الشرير بمقتضى سوء تصرفاته، أما الصديق فله معتصم عند موته.","14:33":"في قلب الفطن تستقر الحكمة، ويخلو منها قلب الجهال.","14:34":"البر يسمو بالأمة، والخطيئة عار لكل شعب.","14:35":"العبد العاقل يحظى برضى الملك، والعبد المخزي يستجلب سخطه.","15:1":"الجواب اللين يبدد الغضب، والكلمة القارصة تهيج السخط.","15:2":"لسان الحكيم يتقن المعرفة، وأقوال الجهال تفيض حماقة.","15:3":"عينا الرب في كل مكان تراقبان الأشرار والأخيار.","15:4":"اللسان السليم ينعش كشجرة حياة، واعوجاجه يؤدي إلى انكسار الروح.","15:5":"الجاهل يستخف بتأديب أبيه، أما العاقل فيقبل التأديب.","15:6":"في بيت الصديق كنز نفيس، وفي دخل الأشرار بلية.","15:7":"أقوال شفاه الحكماء تنشر المعرفة، أما قلوب الجهال فتنبع حماقة.","15:8":"قربان المنافقين مكرهة الرب، ومسرته صلاة المستقيمين.","15:9":"سلوك الشرير رجس لدى الرب، ومحبته لمن يتبع البر.","15:10":"المنحرف عن طريق الرب يجازى بالتأديب القاسي، ومن يمقت التقويم يموت.","15:11":"أعماق الهاوية والهلاك مكشوفة أمام الرب، فكم بالحري قلوب أبناء البشر.","15:12":"المستهزيء يكره التوبيخ، ولا يلجأ إلى الحكماء.","15:13":"القلب الفرح يجعل الوجه طلقا، وبكآبة القلب تنسحق الروح.","15:14":"قلب الحكيم يلتمس المعرفة، وفم الجاهل يرعى حماقة.","15:15":"جميع أيام البائس شقية، أما طيب القلب فالتوفيق الدائم حليفه.","15:16":"قليل من المال مع تقوى الرب خير من كنز عظيم يخالطه هم.","15:17":"أكلة من البقول في جو مشبع بالمحبة خير من أكل وجبة من لحم عجل معلوف في جو من البغضاء.","15:18":"الرجل الغضوب يثير الخصومة، والطويل الأناة يسكن النزاع.","15:19":"طريق الكسول مملوء بالمتاعب، أما سبيل المستقيمين فممهد.","15:20":"الابن الحكيم يسر أباه والجاهل يحتقر أمه.","15:21":"الحماقة مصدر فرح للغبي، أما الفهيم فيسلك باستقامة.","15:22":"تخفق المقاصد من غير مشورة، وتفلح بكثرة المشيرين.","15:23":"الجواب الملائم يفرح الإنسان، وما أحسن الكلمة في حينها.","15:24":"طريق الإنسان الحكيم ترتقي به صعودا نحو الحياة، لكي يتفادى الهاوية من تحت.","15:25":"يستأصل الرب بيت المتغطرسين، ويوطد تخم الأرملة.","15:26":"نوايا الأشرار رجس لدى الرب، وفي أقوال الأطهار مسرته.","15:27":"الحريص على الكسب يجلب المتاعب لبيته، ومن يكره الرشوة يحيا.","15:28":"قلب الصديق يتمعن في الجواب، أما أفواه الأشرار فتتدفق بالخبائث.","15:29":"الرب بعيد عن الأشرار، إنما يسمع صلاة الأبرار.","15:30":"البهجة المتألقة في العينين تفرح قلب الصديق، والخبر الطيب ينعش النفس.","15:31":"ذو الأذن المستمعة إلى التوبيخ المحيي يمكث بين الحكماء.","15:32":"من يتجاهل التأديب يحتقر نفسه، ومن يستجيب له يقتني فهما.","15:33":"تقوى الرب تأديب حكمة، وقبل الحظوة بالكرامة يكون التواضع.","16:1":"يسعى الإنسان بالتفكير والتدبير، إنما الرب يعطي الجواب الفاصل.","16:2":"جميع تصرفات الإنسان تبدو نقية في عيني نفسه، ولكن الرب مطلع على حوافز الأرواح.","16:3":"اطرح على الرب أعمالك فتثبت مقاصدك.","16:4":"لكل شيء صنعه الرب غرض في ذاته، حتى الشرير ليوم الضيق.","16:5":"كل متكبر القلب رجس عند الرب، ولن يفلت حتما من العقاب.","16:6":"بالرحمة والحق يستر الإثم، وبتقوى الرب يتفادى الإنسان الوقوع في الشر.","16:7":"إذا رضي الرب عن تصرفات الإنسان، جعل أعداءه أيضا يسالمونه.","16:8":"المال القليل مع العدل خير من دخل وفير حرام.","16:9":"عقل الإنسان يسعى في تخطيط طريقه، والرب يوجه خطواته.","16:10":"تنطق شفتا الملك بالوحي، وفمه لا يخون في القضاء.","16:11":"للرب ميزان العدل وقسطاسه، وجميع معايير كيس التاجر من صنعه.","16:12":"من الرجس أن يرتكب الملك الشر، لأن العرش يقوم على البر.","16:13":"الشفاه الناطقة بالعدل مسرة الملوك، وهم يحبون المتكلم بالحق.","16:14":"غضب الملك رسول الموت، وعلى الحكيم استرضاؤه.","16:15":"في بشاشة وجه الملك حياة، ورضاه كسحاب المطر المتأخر.","16:16":"اقتناء الحكمة أفضل من الذهب، وإحراز الفطنة خير من الفضة.","16:17":"منهج المستقيمين تفاديهم سبيل الشر، ومن يصون مسلكه يصون نفسه.","16:18":"قبل الانكسار الكبرياء، وقبل السقوط غطرسة الروح.","16:19":"اتضاع الروح مع الودعاء خير من اقتسام الغنيمة مع المتكبرين.","16:20":"من يتعقل بكلمة الله يحالفه التوفيق، وطوبى لمن يتكل على الرب.","16:21":"الحكيم القلب يدعى فهيما، وعذوبة المنطق تزيد من قوة الإقناع.","16:22":"الفطنة ينبوع حياة لصاحبها، وعقاب الجاهل في حماقته.","16:23":"عقل الحكيم يرشد فمه، ويزيد منطقه قوة إقناع.","16:24":"عذوبة الكلام شهد عسل، حلو للنفس وعافية للجسد.","16:25":"رب طريق تبدو للإنسان قويمة ولكن عاقبتها تفضي إلى دروب الموت.","16:26":"شهية العامل حافز عمله، لأن فمه الجائع يحثه عليه.","16:27":"الرجل اللئيم ينبش الشر، وعلى شفتيه تتوهج نار متقدة.","16:28":"المنافق يثير الخصومات، والنمام يفرق الأصدقاء.","16:29":"الرجل الجائر يستغوي قريبه، ويجعله يتنكب عن سواء السبيل.","16:30":"من يغمز بعينيه هو متآمر بالمكائد، ومن يعض على شفتيه فقد أتم خطة الشر.","16:31":"الشيبة إكليل بهاء، ولا سيما في طريق البر.","16:32":"البطيء الغضب خير من المحارب العاتي، والضابط أهواء روحه خير من قاهر المدن.","16:33":"تلقى القرعة في الحضن، ولكن القرار مرهون كله لأمر الرب.","17:1":"لقمة خبز جافة مصحوبة بالسلام خير من بيت مليء بذبائح ويسوده الخصام.","17:2":"العبد العاقل يسود على الابن الفاجر، ويشارك الإخوة في الميراث.","17:3":"كما تنقي البوتقة الفضة، والكور الذهب، فإن الرب يمتحن القلوب أيضا.","17:4":"فاعل الإثم يصغي لكلام الشر، والكاذب يتجاوب مع أقوال السوء.","17:5":"المستهزيء بالفقير يحتقر صانعه، والشامت بالبلية لا يفلت من العقاب.","17:6":"تاج الشيوخ الأحفاد، وفخر الأبناء آباؤهم.","17:7":"لا يصح للجاهل أن ينطق بمأثور القول، وأشر منه الكذب على الرجل النبيل.","17:8":"الرشوة تعويذة في عيني مهديها، وحيثما توجه يفلح.","17:9":"من يصفح عن الذنب يلتمس المحبة، والواشي يفرق بين الأصدقاء الحميمين.","17:10":"يؤثر التأنيب في الحكيم أكثر من تأثير مئة جلدة في الجاهل.","17:11":"الشر ير يسعى فقط للتمرد، فينقض عليه رسول قاس.","17:12":"مصادفة دبة ثاكل خير من مصادفة جاهل متورط في حماقته.","17:13":"من يجازي خيرا بشر، لن يبرح الشر من بيته.","17:14":"بداية الخصام كتفجر المياه، فاترك الخصام قبل انفجاره.","17:15":"مبريء المذنب ومذنب البريء كلاهما رجس عند الرب.","17:16":"ما جدوى أن يكون لدى الجاهل مال لاقتناء الحكمة، وهو لا يملك الفهم لتعلمها.","17:17":"الصديق يحب في كل حين، والأخ يولد ليكون عونا في الضيق.","17:18":"الأحمق من يكفل سواه بصفق الكف، ويضمن جاره ضمانا كاملا","17:19":"من يحب الإثم يحب المشاجرة، ومن يكثر من المباهاة يجلب على نفسه الدمار.","17:20":"ذو القلب المعوج لا يفلح، وصاحب اللسان المنافق يقع في البلية.","17:21":"من أنجب جاهلا صار غما له، وأبو الأحمق لا يعرف الفرح.","17:22":"القلب المسرور دواء شاف، والروح المنسحقة تبلي العظام.","17:23":"الشرير يأخذ الرشوة من الحضن ليحرف سير القضاء.","17:24":"الحكمة هي غاية العاقل أما عينا الجاهل فزائغتان إلى أقاصي الأرض.","17:25":"الابن الجاهل مبعث تعاسة لأبيه، ومرارة قلب لأمه.","17:26":"أيضا لا يليق تغريم البريء، ولا جلد الشرفاء تقويما لهم.","17:27":"ذو المعرفة يتروى في كلماته، والعاقل ذو رباطة جأش.","17:28":"حتى الجاهل، إن صمت، يحسب حكيما، وإن أطبق شفتيه يحسب عاقلا.","18:1":"المعتزل (عن الله والناس) ينشد شهوته ويتنكر لكل مشورة صائبة.","18:2":"لا يعبأ الجاهل بالفطنة، بل همه الإعراب عما في نفسه.","18:3":"إذا أقبل الشرير أقبل معه الاحتقار، والعار يلازم الهوان.","18:4":"كلمات الإنسان مياه عميقة يتعذر سبر غورها، وينبوع الحكمة نهر متدفق.","18:5":"من السوء محاباة الشرير، أو حرمان البريء من القضاء الحق.","18:6":"أقوال الجاهل توقعه في المتاعب، وكلماته تسبب له الضرب.","18:7":"كلمات الجاهل مهلكة له، وأقواله فخ لنفسه.","18:8":"همسات النمام كلقم سائغة تنزلق إلى بواطن الجوف.","18:9":"المتقاعس عن عمله هو أخو الهادم.","18:10":"اسم الرب برج منيع يهرع إليه الصديق وينجو من الخطر.","18:11":"ثروة الغني مدينته الحصينة، وهي في وهمه سور شامخ.","18:12":"قبل الانكسار تشامخ القلب، وقبل الكرامة التواضع.","18:13":"من أجاب عن أمر مازال يجهله، فذاك حماقة منه وعار له.","18:14":"روح الإنسان القوية تحتمل مرضه، أما الروح المنسحقة فمن يتحملها؟","18:15":"عقل الفهيم يقتني معرفة، وأذن الحكماء تنشد علما.","18:16":"هدية الإنسان تمهد له السبيل، وتجعله يمثل أمام العظماء.","18:17":"من يعرض قضيته أولا يبدو محقا إلى أن يأتي آخر ويستجوبه.","18:18":"تفصل القرعة في الخصومات وتحسم الأمر بين المتنازعين الأقوياء.","18:19":"إرضاء الأخ المتأذي أصعب من قهر مدينة حصينة، والمخاصمات كعارضة قلعة.","18:20":"من ثمر أقوال الإنسان تشبع ذاته، ومن غلة كلماته يلقى جزاءه","18:21":"في اللسان حياة أو موت، والمولعون باستخدامه يتحملون العواقب.","18:22":"من عثر على زوجة صالحة نال خيرا وحظي بمرضاة الله.","18:23":"يتوسل الفقير بتضرعات، أما الغني فيجاوب بخشونة.","18:24":"من يكثر الأصحاب يخرب نفسه، ورب صديق ألزق من الأخ.","19:1":"الفقير السالك بكماله خير من الجاهل المخاتل.","19:2":"لا يجدر بالمرء أن يخلو من المعرفة، ومن يتعجل الأمور يخطيء الغرض.","19:3":"عندما تسيء حماقة الإنسان إلى حياته، يسخط قلبه على الله.","19:4":"الغني يجتذب كثرة من الأصدقاء، أما الفقير فيهجره خليله.","19:5":"شاهد الزور لا ينجو من العقاب، ونافث الكذب لا يفلت من القصاص.","19:6":"كثيرون يتملقون صاحب النفوذ، والكل صاحب للذي يغدق العطايا.","19:7":"جميع إخوة الفقير يمقتونه، فما أحرى أن يتهرب منه أصدقاؤه؛ يلاحقهم بتوسلاته ولا يجد لهم أثرا.","19:8":"من اقتنى حكمة أحب نفسه، ومن ادخر الفهم يلقى خيرا.","19:9":"شاهد الزور لا يفلت من العقاب، ونافث الأكاذيب يهلك.","19:10":"لا يليق التنعم بالجاهل، فكم بالحري أن يتسلط على الرؤساء؟","19:11":"تعقل الإنسان يكبح غضبه، وبهاؤه في العفو عن الخطأ.","19:12":"حنق الملك كزمجرة الأسد، ورضاه كالطل على العشب.","19:13":"الابن الجاهل مدعاة خراب لأبيه، ومخاصمات الزوجة كنقر قطرات المطر المتتابعة،","19:14":"البيت والثروة ميراث من الآباء، أما الزوجة العاقلة فهي من عند الرب.","19:15":"الكسل يغرق في سبات عميق، والنفس المتقاعسة تقاسي من الجوع.","19:16":"من يطيع الوصية يصون نفسه، والمتهاون في تصرفاته يلقى الموت.","19:17":"من يرحم الفقير يقرض الرب، ويكافئه الرب على حسن صنيعه.","19:18":"أدب ابنك مادام في ذلك رجاء، ولا تحمل نفسك على قتله.","19:19":"الجامح الغضب يدفع ثمن جموحه، وإن كبحته أو اعترضته فإنك تزيده سوءا","19:20":"استمع إلى المشورة، واقبل التأديب، فتكتسب حكمة بقية حياتك.","19:21":"كثيرة هي نوايا قلب الإنسان، إنما مشورة الرب هي التي تسود.","19:22":"حسن الجميل زينة الناس، والفقير خير من الغني الكاذب.","19:23":"تقوى الرب تفضي إلى الحياة، وصاحبها يبيت مطمئنا ولا يناله شر.","19:24":"الكسول يدفن يده في صحنه ولا يردها حتى إلى فمه.","19:25":"اضرب المستهزيء فيتعقل الأحمق، ووبخ العاقل فيكتسب فهما.","19:26":"من يخرب حياة أبيه، ويشرد أمه هو ابن يجلب الخزي والعار.","19:27":"كف ياابني عن الإصغاء إلى التعليم الذي يضلك عن كلمات المعرفة.","19:28":"الشاهد المنافق يسخر من القضاء، وفم الأشرار يبتلع الإثم.","19:29":"العقاب معد للساخرين، وجلد السياط مهيَّأ لظهور الجهال.","20:1":"الخمر مستهزئة، والمسكر صخاب، ومن يدمن عليها فليس بحكيم.","20:2":"سخط الملك مثل زمجرة الأسد، ومن يثير غيظه يسيء إلى نفسه.","20:3":"من دواعي شرف المرء أن يتفادى الخصومة، والأحمق يخوض معترك النزاع.","20:4":"لا يحرث الكسول في الموسم خشية البرد، وفي أوان الحصاد يطلب غلة فلا يجد.","20:5":"نوايا قلب المرء كماء عميق والعاقل من يستخرجها.","20:6":"كثيرون يدعون الصلاح، أما الأمين فمن يعثر عليه؟","20:7":"الصديق يسلك بكماله، فطوبى لأبنائه من بعده.","20:8":"الملك المتربع على عرش القضاء يغربل بعينه البصيرة الخير من كل شر.","20:9":"من يدعي قائلا: إني نقيت قلبي، وتطهرت من خطيئتي؟","20:10":"الغش ما بين أوزان ومعايير ومكاييل الشراء، وأوزان ومعايير ومكاييل البيع رجس لدى الرب.","20:11":"حتى الصبي يكشف بتصرفه هل عمله نقي وقويم أم لا.","20:12":"الله هو صانع الأذن المطيعة والعين البصيرة.","20:13":"لا تولع بالنوم لئلا تفتقر، استيقظ واعمل فتشبع خبزا.","20:14":"يقول المشتري: هذه بضاعة رديئة! هذه بضاعة رديئة! وإذا مضى بها في حال سبيله يشرع في الافتخار.","20:15":"مع أن الذهب موجود واللآليء كثيرة، فإن الشفاه الناطقة بالمعرفة جوهرة نادرة.","20:16":"خذ ثوب المرء الذي ضمن غريبا، وارتهنه منه، لأنه كفل أجنبيا.","20:17":"الخبز المكتسب حراما سائغ في حلق الإنسان، إنما لا يلبث أن يمتليء فمه حصى!","20:18":"بالمشورة تترسخ المقاصد، وبحسن الدراية خض حربا.","20:19":"الواشي يفشي الأسرار، فلا تخالط من يكثر الثرثرة.","20:20":"من يشتم أباه أو أمه يطفيء الرب سراج حياته في الظلمة الحالكة.","20:21":"رب ملك يورث على عجل في بدايته، يفتقر إلى البركة في نهايته.","20:22":"لا تقل: لأجازين من أساء إلي شرا. انتظر، فالرب يعينك.","20:23":"التلاعب بالمعايير رجس عند الرب، وميزان الغش أمر رديء.","20:24":"خطوات الإنسان يوجهها الرب، فكيف يمكن للمرء أن يفهم طريقه؟","20:25":"شرك للإنسان أن يتسرع في النذر للرب ثم يندم على ما نذر.","20:26":"الملك الحكيم يغربل الأشرار، ثم يسحقهم بالنوارج،","20:27":"نفس الإنسان سراج الرب الذي يبحث في كل أغوار ذاته.","20:28":"الرحمة والحق يحفظان الملك، وبالرحمة يدعم عرشه.","20:29":"فخر الشبان في قوتهم، أما بهاء الشيوخ ففي مشييهم.","20:30":"جروح الضربات تنقي من الشرور، والجلدات تطهر أغوار النفس.","21:1":"قلب الملك في يد الرب كجداول مياه يميله حيثما شاء.","21:2":"جميع تصرفات الإنسان تبدو نقية في عيني نفسه، ولكن الرب مطلع على حوافز القلوب.","21:3":"إجراء العدل والحق أكثر قبولا عند الرب من الذبيحة.","21:4":"تشامخ العينين من غطرسة القلب، وسراج الأشرار خطيئة.","21:5":"خطط المجتهد تفضي حتما إلى الخصب، والعجول مصيره العوز.","21:6":"ادخار الكنوز بلسان منافق، دخان متلاش وفخ مميت.","21:7":"جور الأشرار يجرفهم لرفضهم إجراء العدل.","21:8":"طريق المذنب معوجة، أما تصرف الزكي فقويم.","21:9":"الإقامة في ركن سطح خير من مشاطرة بيت مع زوجة نكدة.","21:10":"نفس المنافق تشتهي الشر، وقريبه لا يحظى برضاه.","21:11":"إذا عوقب المستهزيء صار الجاهل حكيما، وإن أرشد الحكيم اكتسب معرفة.","21:12":"يتأمل الصديق في بيت الشرير، (فيراه) يلقى به إلى البلايا.","21:13":"من أصم أذنه عن صراخ المسكين، يصرخ هو أيضا ولا من مجيب.","21:14":"الهدية في الخفاء تخمد الغضب، والرشوة في الحضن تسكن السخط.","21:15":"الحكم بالعدل فرح للصديق، ورعب لفاعلي الإثم.","21:16":"الرجل الشارد عن طريق المعرفة يسكن بين جماعة الموتى.","21:17":"عاشق اللذة فقير، والمولع بالخمر والطيب لا يغتني.","21:18":"الشرير فداء عن الصديق، والغادر عن المستقيمين.","21:19":"الإقامة في أرض مقفرة خير من السكنى مع امرأة مشاكسة شرسة.","21:20":"في بيت الحكيم كنوز وزيت مدخرة، أما الإنسان الجاهل فيتلف ما لديه.","21:21":"من اتبع العدل والرحمة يلقى الحياة والحق والمجد.","21:22":"الحكيم يتسلق سور مدينة الجبابرة ويدمر معقل اعتمادهم","21:23":"من يصون فمه ولسانه عن اللغو يحفظ نفسه من المتاعب.","21:24":"المتشامخ المنتفخ يدعى المستهزيء لأنه يتصرف بغرور الكبرياء.","21:25":"أوهام الكسول تقتله لأن يديه تأبيان العمل.","21:26":"يظل طوال النهار متشهيا متمنيا، أما الصديق فيسخو ولا يضن","21:27":"ذبيحة الشرير رجس عند الرب، فكم بالحري إن قربها بنية أثيمة؟","21:28":"شاهد الزور يهلك، أما أقوال الرجل الحريص على الاستماع فتدوم.","21:29":"الرجل الشرير يغلظ وجهه، أما المستقيم فيعمل على تقويم طرقه.","21:30":"ليس من حكمة، ولا من مشورة، ولا من فطنة بقادر ة على مقاومة الله.","21:31":"مع أن الفرس معد ليوم القتال، فإن النصر هو من عند الله.","22:1":"الصيت مفضل على الغنى الطائل، ونعمة المعروف خير من الذهب والفضة.","22:2":"الغني والفقير متماثلان إذ إن الرب هو صانعهما.","22:3":"يرى العاقل الشر فيتوارى، أما الجاهل فيقبل إليه ويعاقب.","22:4":"ثواب التواضع وتقوى الرب هو الغنى والكرامة والحياة.","22:5":"في طريق الملتوي شوك وأشراك، ومن يصون نفسه يتفاداها.","22:6":"درب الولد بمقتضى مواهبه وطبيعته، فمتى شاخ لا يميل عنها.","22:7":"الغني يسود على الفقير، والمقترض مستعبد للمقرض.","22:8":"من زرع جورا يحصد بلية، ويفقد ما له من سلطان.","22:9":"الجواد يتمتع بالبركة لأنه يقتسم خبزه مع الفقير.","22:10":"اطرد المستهزيء، فيخرج الخصام، ويتوقف الشجار والإساءة.","22:11":"من يحب طهار ة القلب، ويتحلى بعذوبة الحديث، يضحى الملك صديقا له.","22:12":"عينا الرب ترعيان المعرفة، وهو يخرب كلام الغادرين.","22:13":"قال الكسول: في الخارج أسد يفترسني إن خرجت إلى الشوارع.","22:14":"فم العاهرة حفرة عميقة فمن سخط الرب عليه يهوي فيها.","22:15":"الحماقة متأصلة في قلب الولد، وعصا التأديب تطردها منه.","22:16":"من يجور على الفقير ليثرى ظلما، ومن يهدي الغني (على حساب الفقير) يؤول به الأمر إلى الفاقة.","22:17":"أرهف أذنك واستمع لكلام الحكماء، وليعزم قلبك على إدراك معرفتي،","22:18":"فتطيب إن حفظتها في قرارة نفسك، وأثبتها دائما على شفتيك.","22:19":"إياها قد لقنتك أنت اليوم ليكون اتكالك على الرب.","22:20":"ألم أكتب لك ثلاثين قولا من مأثور المشورة والحكم؟","22:21":"لأعلمك قول الحق اليقين لترد جواب صدق للذين أرسلوك.","22:22":"لا تسلب الفقير لأنه فقير، ولا تسحق البائس الماثل عند الباب،","22:23":"لأن الرب يدافع عن دعواهم، ويهلك ناهبيهم.","22:24":"لا تصادق رجلا غضوبا، ولا ترافق رجلا ساخطا،","22:25":"لئلا تألف تصرفاته، وتوقع نفسك في الشرك.","22:26":"لا تكن من الذين يضمنون غيرهم بصفق الكف، ولا من كافلي الديون،","22:27":"إن لم يكن عندك ما يفي الدين، فلماذا يصادرون فراشك الذي تنام عليه؟","22:28":"لا تنقل معالم التخم القديم الذي أقامه آباؤك.","22:29":"أرأيت الإنسان المجد في عمله؟ إنه يمثل أمام الملوك لا أمام الرعاع!","23:1":"إذا جلست تأكل مع حاكم، فتأمل أشد التأمل فيما هو أمامك.","23:2":"ضع سكينا في حلقك إن كنت شرها!","23:3":"لا تشته أطايبه لأنها أطعمة خادعة.","23:4":"لا تشق طلبا للثراء. اكبح جماح نفسك بفضل فطنتك.","23:5":"ما تكاد تتألق عيناك حبورا به حتى يتبدد، إذ فجأة يصنع لنفسه أجنحة ويطير كالنسر محلقا نحو السماء.","23:6":"لا تأكل من خبز رجل بخيل، ولا تشته أطايبه،","23:7":"لأنه يفكر دائما في الثمن. يقول لك: كل واشرب، إلا أن قلبه يكن لك غير ذلك،","23:8":"فتتقيأ اللقم التي أكلتها وتذهب كلمات إطرائك سدى!","23:9":"لا تتكلم في مسامع الجاهل لأنه يزدري بحكمة أقوالك.","23:10":"لا تنقل معالم تخم قديم، ولا تدخل حقول الأيتام،","23:11":"لأن وليهم قادر، وهو يدافع عن دعواهم ضدك.","23:12":"وجه قلبك إلى التأديب، وأرهف أذنيك لكلمات المعرفة.","23:13":"لا تمتنع عن تأديب الولد. إن عاقبته بالعصا لا يموت.","23:14":"اضربه بالعصا، فتنقذ نفسه من الهاوية.","23:15":"ياابني إن كان قلبك حكيما، يبتهج قلبي أيضا،","23:16":"تفرح نفسي عندما تنطق شفتاك بالحق.","23:17":"لا يغر قلبك من الخطاة، بل واظب على تقوى الرب اليوم كله،","23:18":"فهناك حقا ثواب، ورجاؤك لن يخيب.","23:19":"استمع ياابني وكن حكيما، ووجه قلبك نحو سبيل الحق.","23:20":"لا تكن واحدا من مدمني الخمر، الشرهين لالتهام اللحم،","23:21":"لأن السكير والشره يفتقران، وكثرة النوم تكسو المرء بالخرق.","23:22":"استمع لأبيك الذي أنجبك، ولا تحتقر أمك إذا شاخت.","23:23":"اقتن الحق ولا تبعه، وكذا الحكمة والتأديب والفطنة.","23:24":"أبو الصديق يغتبط أشد الاغتباط، ومن أنجب حكيما يسر به.","23:25":"ليفرح أبوك وأمك ولتبتهج من أنجبتك.","23:26":"يا ابني هبني قلبك، ولتراع عيناك سبلي.","23:27":"فإن العاهرة حفرة عميقة، والزوجة الماجنة بئر ضيقة،","23:28":"تكمن متر بصة كلص، وتزيد من الغادرين بين الناس.","23:29":"لمن المعاناة؟ لمن الويل والشقاء والمخاصمات والشكوى؟ لمن الجر اح بلا سبب؟ ولمن احمرار العينين؟","23:30":"إنها للمدمنين الخمر، الساعين وراء المسكر الممزوج.","23:31":"لا تنظر إلى الخمر إذا التهبت بالاحمرار، وتألقت في الكأس، وسالت سائغة،","23:32":"فإنها في آخرها تلسع كالحية وتلدغ كالأفعوان.","23:33":"فتشاهد عيناك أمورا غريبة، وقلبك يحدثك بأشياء ملتوية،","23:34":"فتكون مترنحا كمن يضطجع في وسط عباب البحر، أو كراقد على قمة سارية!","23:35":"فتقول: «ضر بوني ولكن لم أتوجع. لكموني فلم أشعر، فمتى أستيقظ؟ سأذهب ألتمس شربها مرة أخرى».","24:1":"لا تحسد أهل الشر، ولا تشته معاشرتهم،","24:2":"لأن قلوبهم تتآمر على ارتكاب الظلم، وألسنتهم تنطق بالإساءة.","24:3":"بالحكمة يبنى البيت، وبالفهم يرسخ.","24:4":"بالمعرفة تكتظ الحجرات بكل نفيس، وكنوز نادرة.","24:5":"الرجل الحكيم يتمتع بالعزة، وذو المعرفة يزداد قوة،","24:6":"لأنك بحسن التدبير تخوض حربك، وبكثرة المشيرين يكون الخلاص.","24:7":"الحكمة أسمى من أن يدركها الجاهل، وفي ساحة المدينة لا يفتح فاه!","24:8":"المتفكر في ارتكاب الشر يدعى متآمرا.","24:9":"نوايا الجاهل خطيئة، والمستهزيء رجس عند الناس.","24:10":"إن عييت في يوم الضيق تكون واهن القوى.","24:11":"أنقذ المسوقين إلى الموت ورد المتعثرين الذاهبين إلى الذبح.","24:12":"إن قلت: إننا لم نعرف هذا، أفلا يفهم هذا وازن القلوب؟ ألا يدركه راعي النفوس، فيجازي الإنسان بمقتضى عمله؟","24:13":"ياابني، كل عسلا لأنه طيب، وكذلك الشهد لأنه حلو لمذاقك.","24:14":"لذلك التمس الحكمة لنفسك، فإذا وجدتها تحظى بالثواب ولا يخيب رجاؤك.","24:15":"لا تكمن كما يكمن الشرير لمسكن الصديق ولا تدمر منزله،","24:16":"لأن الصديق يسقط سبع مرات، ومع ذلك ينهض، أما الأشرار فيتعثرون بالشر.","24:17":"لا تشمت لسقوط عدوك، ولا يبتهج قلبك إذا عثر،","24:18":"لئلا يشهد الرب، فيسوء الأمر في عينيه ويصرف غضبه عنه.","24:19":"لا يتآكل قلبك غيظا من فاعلي الإثم، ولا تحسد الأشرار،","24:20":"إذ لا ثواب للشرير، وسراجه ينطفيء.","24:21":"ياابني اتق الرب والملك، ولا تعاشر المتقلبين،","24:22":"لأن هذين الإثنين ينزلان البلية بغتة عليهم. ومن يدري أية كوارث تصدر عنهما؟","24:23":"وهذه أيضا أقوال الحكماء: التحيز في الحكم مشين،","24:24":"ومن يقول للشرير: أنت بريء، تلعنه الشعوب وتمقته الأمم.","24:25":"أما الذين يوبخونه فلهم الغبطة وتحل عليهم بركة الخير.","24:26":"من يجيب بقول صائب يحظى بالكرامة.","24:27":"أنجز عملك في الخارج وهييء حقلك لنفسك، ثم ابن بيتك.","24:28":"لا تشهد ضد قريبك من غير داع، فلماذا تنطق شفتاك زورا؟","24:29":"لا تقل: سأعامله بمثل ما عاملني، وأجازيه على ما ارتكبه في حقي.","24:30":"اجتزت في حقل الكسول وبكرم الرجل الفاقد البصيرة،","24:31":"وإذا بالشوك قد كساه، والعوسج قد غطى كل أرضه، وجدار حجارته قد انهار،","24:32":"فاعتبر قلبي بما شاهدت، وتلقنت درسا مما رأيت.","24:33":"أدركت أن قليلا من النعاس بعد قليل من النوم، وطي اليدين للهجوع،","24:34":"تجعل الفقر يقبل عليك كقاطع طريق والفاقة كغاز مسلح!","25:1":"هذه أيضا أمثال سليمان التي نسخها رجال حزقيا ملك يهوذا:","25:2":"من مظاهر مجد الله كتمان أسراره، أما مظاهر مجد الملك فالكشف عن بواطن الأمور.","25:3":"كما أن السماوات للعلو، والأرض للعمق، فإن قلب الملك لا يسبر غوره.","25:4":"نق الفضة من شوائبها، فيخلص للصائغ ما يصنع منه إناء.","25:5":"أبعد الشرير من حضرة الملك، يتثبت عرشه بالعدل.","25:6":"لا تتباه أمام الملك، ولا تقف في موضع العظماء،","25:7":"لأنه خير أن يقال لك: ارتفع إلى هنا من أن يحط مقامك في حضرة الرئيس، الذي شاهدته عيناك.","25:8":"لا تتسرع بالذهاب إلى ساحة القضاء، إذ ماذا تفعل في النهاية إن أخزاك قريبك؟","25:9":"قم بمناقشة دعواك مع قريبك، ولا تفش سر غيرك،","25:10":"لئلا يعيرك السامع، ولا تمحى فضيحتك.","25:11":"كلمة تقال في أوانها مثل تفاح من ذهب في مصوغ من فضة.","25:12":"الموبخ الحكيم لأذن صاغية مثل قرط من ذهب وحلي من إبريز.","25:13":"الرسول الأمين لمرسليه مثل برودة الثلج في يوم الحصاد، لأنه ينعش نفوس سادته.","25:14":"المتفاخر بإغداق هدايا كاذبة هو كالسحاب والريح بلا مطر.","25:15":"بالصبر يتم إقناع الحاكم، واللسان اللين يكسر العظام.","25:16":"إن عثرت على عسل فكل منه ما يكفيك، لئلا تتخم فتتقيأه،","25:17":"أقلل من زيارة قريبك لئلا يسأم منك ويمقتك.","25:18":"شاهد الزور ضد قريبه هو مثل مطرقة وسيف وسهم مسنون.","25:19":"الاعتماد على الغادر في وقت الضيق مثل سن مهتومة أو رجل مخلعة.","25:20":"من يشدو بالأغاني لقلب كئيب يكون كنزع الثوب في يوم قارس البرودة، أو كخل على نطرون.","25:21":"إن جاع عدوك فأطعمه، وإن عطش فاسقه،","25:22":"فإن فعلت هذا تجمع جمرا على رأسه، والرب يكافئك.","25:23":"ريح الشمال تجلب المطر، واللسان النمام يستأثر بالنظرات الغاضبة.","25:24":"الإقامة في ركن سطح خير من مشاطرة بيت مع زوجة نكدة.","25:25":"الخبر الطيب من أرض بعيدة مثل ماء بارد للنفس الظامئة.","25:26":"الصديق المتخاذل أمام الشرير هو عين عكرة وينبوع فاسد.","25:27":"كما أن الإكثار من التهام العسل مضر، كذلك التماس المجد الذاتي مدعاة للهوان.","25:28":"الرجل المفتقر لضبط النفس مثل مدينة منهدمة لا سور لها.","26:1":"الكرامة لا تليق بالجاهل، فهي كالثلج في الصيف، وكالمطر في موسم الحصاد.","26:2":"اللعنة من غير علة لا تستقر، فهي كالعصفور الحائم واليمامة المهومة.","26:3":"السوط للفرس، واللجام للحمار، والعصا لظهور الجهال.","26:4":"لا تجب الجاهل بمثل حمقه لئلا تصبح مثله.","26:5":"رد على الجاهل حسب جهله لئلا يضحى حكيما في عيني نفسه.","26:6":"من يبعث برسالة على فم جاهل يكون كمن يبتر الرجلين أو يجرع الظلم.","26:7":"المثل في فم الجهال كساقي الأعرج المتهدلتين.","26:8":"مثل من يكرم الجاهل كمثل من يضرب حجرا في مقلاع (ويقذفه بعيدا).","26:9":"المثل في فم الجهال كشوك في يد سكران.","26:10":"من يستأجر الجاهل أو أي عابر طريق، يكون كرامي سهام، يصيب على غير هدى.","26:11":"كما يعود الكلب إلى قيئه، هكذا يعود الجاهل ليرتكب حماقته.","26:12":"أشاهدت رجلا معتزا بحكمته؟ إن للجاهل رجاء في الإصلاح أكثر منه.","26:13":"يقول الكسول: في الطريق أسد، وفي الشوارع ليث.","26:14":"كما يدور الباب على مفاصله، يتقلب الكسول في فراشه.","26:15":"يدفن الكسول يده في صحفته ويشق عليه أن يردها إلى فمه.","26:16":"الكسول أكثر حكمة في عيني نفسه من سبعة يجيبون بفطنة.","26:17":"من يتدخل في خصومة لا تعنيه يكون كمن يقبض على أذني كلب عابر.","26:18":"كمجنون يقذف شررا وسهاما وموتا،","26:19":"من يخدع قريبه، ثم يقول: كنت أمزح فقط!","26:20":"كما تخمد النار لافتقارها إلى الحطب، هكذا تكف الخصومة حينما يغيب النمام.","26:21":"كما أن الفحم يزيد من اتقاد الجمر، والحطب من اشتعال النار، هكذا صاحب الخصومة يضرم النزاع.","26:22":"همسات النمام كلقم سائغة تنزلق إلى بواطن الجوف!","26:23":"الشفتان المتوهجتان والقلب الشرير مثل فضة زغل تغطي خزفة.","26:24":"الرجل الماكر يطلي نواياه بمعسول الشفاه، ولكنه يراعي الحقد في قلبه،","26:25":"إن تملقك بعذوبة حديثه، فلا تأتمنه، لأن قلبه مفعم بسبعة صنوف من الرجاسات.","26:26":"إن وارى حقده بمكر، فإن نفاقه يفتضح بين الجماعة.","26:27":"من يحفر حفرة لإيذاء غيره يقع فيها، ومن دحرج حجرا يرتد عليه.","26:28":"اللسان الكاذب يمقت ضحاياه، والفم الملق يسبب خرابا.","27:1":"لا تتباه بالغد لأنك لا تدري ماذا يلد اليوم.","27:2":"ليثن عليك سواك لا فمك؛ ليمدحك الغريب لا شفتاك.","27:3":"الحجر ثقيل، وحمولة الرمل مرهقة، ولكن غضب الجاهل أثقل منهما.","27:4":"الغضب فظ، والسخط قهار، ولكن من يصمد أمام الغيرة؟","27:5":"التوبيخ الظاهر خير من الحب المضمر.","27:6":"أمينة هي جروح المحب، وخادعة هي قبلات العدو","27:7":"النفس الشبعانة تطأ الشهد، أما النفس الجائعة فتجد كل مر حلوا.","27:8":"الشارد عن موطنه، كالعصفور الشارد عن عشه.","27:9":"الطيب والبخور يفرحان القلب، ومسرة الصديق ناجمة عن المشورة المخلصة.","27:10":"لا تتخل عن صديقك وعن صديق أبيك، ولا تذهب إلى بيت قريبك في يوم بؤسك، وجار قريب خير من أخ بعيد.","27:11":"كن حكيما ياابني، وفرح قلبي، فأرد على معيري وأفحمهم.","27:12":"ذو البصيرة يرى الشر فيتوارى، أما الحمقى فيتقدمون ويقاسون منه.","27:13":"خذ ثوب من كفل الغريب، ورهنا ممن ضمن الأجنبي.","27:14":"من يبارك جاره في الصباح المبكر بصوت مرتفع، تحسب بركته لعنة.","27:15":"قطر ات المطر المتتابعة في يوم ممطر، والمرأة المشاكسة سيان،","27:16":"من يكبح جموحها كمن يكبح الريح، أو كمن يقبض على زيت بيمينه.","27:17":"كما يصقل الحديد الحديد، هكذا يصقل الإنسان صاحبه.","27:18":"من يرعى تينة يأكل من ثمرها، ومن يراعي سيده يحظى بالإكرام.","27:19":"كما يعكس الماء صورة الوجه، كذلك يعكس قلب الإنسان جوهره.","27:20":"كما أن الهاوية والهلاك لا يشبعان، هكذا لا تشبع عينا الإنسان.","27:21":"البوتقة لتنقية الفضة، والأتون لتمحيص الذهب، والإنسان يحكم عليه بموقفه مما يكال له من مديح.","27:22":"لو دققت الأحمق بمدق في هاون مع السميذ، فلن تبرح عنه حماقته.","27:23":"اجتهد في معرفة أحوال غنمك، واحرص كل الحرص على قطعانك.","27:24":"لأن الغنى لا يدوم إلى الأبد، ولا يخلد التاج مدى الدهور.","27:25":"عندما يضمحل العشب، وينمو الحشيش الجديد ويجمع كلأ الجبال،","27:26":"فإن الحملان توفر لك كساءك، وتكون الجداء ثمنا لحقلك.","27:27":"ويكون لك من لبن الماعز قوت يكفيك، وطعام لأهل بيتك وغذاء لجواريك.","28:1":"يهرب الشرير مع أن لا مطارد له، أما الصديقون فشجاعتهم كشجاعة الشبل.","28:2":"عندما يتمرد أهل أرض يكثر رؤساؤهم وتعم الفوضى، ولكنها تدوم إن حكمها ذو فهم ومعرفة.","28:3":"الفقير الجائر على المعوز، كمطر جارف لا يبقي على طعام.","28:4":"من يهمل الشريعة يحمد الشرير، والذي يحافظ عليها يخاصمه.","28:5":"لا يفهم الأشرار العدل، أما ملتمسو الرب فيدركونه تماما.","28:6":"الرجل الفقير السالك بكماله، خير من الغني المنحرف في طرقه.","28:7":"من يحافظ على الشريعة هو ابن حكيم، أما عشير الجشعين فيخجل أباه.","28:8":"المكثر ماله بالربا والاستغلال، إنما يجمعه لمن هو رحيم بالفقراء.","28:9":"من يصرف أذنه عن الاستماع إلى الشريعة، تصير حتى صلاته رجاسة.","28:10":"من يضل المستقيمين ليسلكوا في سبيل الشر، يسقط في حفرته، أما الكاملون فينالون ميراث خير.","28:11":"الغني حكيم في عيني نفسه، لكن الفقير البصير يكتشف حقيقته.","28:12":"عندما يظفر الصديق يشيع الفخر العظيم، لكن حين يتسلط الأشرار يتوارى الناس.","28:13":"من يكتم آثامه لا يفلح، ومن يعترف بها ويقلع عنها يحظى بالرحمة.","28:14":"طوبى للإنسان الذي يتقي الرب دائما، أما من يقسي قلبه فيسقط في البلية.","28:15":"الحاكم العاتي المتسلط على الضعفاء، مثل أسد زائر أو دب ثائر.","28:16":"الحاكم المفتقر إلى الفطنة، هو متسلط جائر. ومن يمقت الربح الحرام يتمتع بعمر مديد.","28:17":"من هو مثقل بارتكاب سفك دم، يظل طريدا حتى وفاته، ولا يعينه أحد.","28:18":"من يسلك بالكمال ينجو، أما المنحرف إلى سبيلين فيسقط في أحدهما.","28:19":"من يفلح أرضه يكثر طعامه، أما من يتبع أوهاما باطلة فيشتد فقره.","28:20":"الرجل الأمين يحظى ببركات غزيرة، والمتعجل إلى الثراء لا يكون بريئا.","28:21":"المحاباة نقيصة، ومن أجل كسرة خبز يرتكب الإنسان الإساءة.","28:22":"ذو العين الشريرة يسعى مسرعا وراء الغنى، ولا يدرك أن الفقر مطبق عليه.","28:23":"من يوبخ إنسانا يحظى من بعد برضاه أكثر ممن يتملق بلسانه.","28:24":"من يسلب أباه وأمه قائلا: ليس في هذا إثم، هو شريك الهادم.","28:25":"الإنسان الجشع يثير النزاع، والمتوكل على الرب يغنى.","28:26":"المتكل على رأيه أحمق، أما السالك في الحكمة فينجو.","28:27":"من يحسن إلى الفقير لا تدركه فاقة ومن يحجب عينيه عنه تنصب عليه لعنات كثيرة.","28:28":"عندما يتسلط الأشرار يتوارى الناس، وعندما يبيدون يكثر الأبرار.","29:1":"من كثر توبيخه وظل معتصما بعناده، يتحطم فجأة ولا شفاء له.","29:2":"إذا ساد الأبرار فرح الشعب، وإذا تسلط الأشرار أن الناس.","29:3":"محب الحكمة يفرح أباه، وعشير الزواني يتلف ماله.","29:4":"بالعدل يشيع الملك الاستقرار في أرضه، والمولع بالرشوة يدمرها.","29:5":"المرء الذي يتملق صاحبه ينشر شبكة لرجليه.","29:6":"الشرير مقتنص في شرك إثمه، أما الصديق فيشدو ويبتهج.","29:7":"الصديق يدرك حق الفقير، أما الشرير فلا يعبأ بمعرفته.","29:8":"المستهزئون يفتنون المدينة، أما الحكماء فيصرفون الغضب.","29:9":"إن خاصم الحكيم سفيها، لن يجد راحة، سواء غضب السفيه أو ضحك.","29:10":"المتعطشون إلى الدماء يكرهون الكامل، والأشرار يلتمسون هلاك المستقيم.","29:11":"الجاهل يفجر غضبه، أما الحكيم فيكبحه بهدوء.","29:12":"إن أصغى الحاكم إلى الأكاذيب، يكون جميع رجال حاشيته أشرارا لأنهم يتملقونه.","29:13":"في هذا يتشابه الفقير والظالم. إن الرب يعطي نورا لعيني كل منهما.","29:14":"عرش الملك القاضي بالحق للفقراء يثبت إلى الأبد.","29:15":"العصا والتأنيب يثمران حكمة، لكن الصبي المهمل يخجل أمه.","29:16":"إذا ساد الأشرار كثرت الآثام، أما الأبرار فيشهدون سقوطهم.","29:17":"قوم ابنك فيريحك، ويشيع المسرة في نفسك.","29:18":"حيث لا رؤيا يجمح الشعب، وطوبى لمن يحفظ الشريعة.","29:19":"لا تؤدب العبد بمجرد الكلام، لأنه وإن فهم لا يستجيب.","29:20":"أرأيت إنسانا متهورا في كلامه؟ إن للجاهل رجاء في الإصلاح أكثر منه.","29:21":"من دلل عبده في حداثته، يتمرد في النهاية عليه.","29:22":"الإنسان الغضوب يثير النزاع، والرجل السخوط كثير المعاصي.","29:23":"كبرياء الإنسان تحط من قدره، والمتواضع الروح يحرز كرامة.","29:24":"شريك اللص يمقت نفسه، يسمع اللعنة ويكتم الجريمة.","29:25":"الخشية من الناس فخ منصوب، أما المتكل على الرب فآمن.","29:26":"كثيرون يلتمسون رضى المتسلط، إنما من الرب يصدر قضاء كل إنسان.","29:27":"الرجل الظالم مكرهة للصديق، وذو السبيل المستقيم رجس عند الشرير.","30:1":"هذه أقوال أجور ابن متقية من قوم مسا، إلى إيثيئيل وأكال:","30:2":"إنني أكثر الناس بلادة، وليس لي فهم إنسان.","30:3":"لم أتلقن الحكمة، ولا أملك معرفة القدوس.","30:4":"من ارتقى إلى السماء ثم هبط منها؟ ومن جمع الريح في حفنتيه؟ من صر المياه في ثوب؟ من أرسى جميع أطراف الأرض؟ ما اسمه وما اسم ابنه؟ أخبرني إن كنت تعلم.","30:5":"كل كلمة من كلمات الله صادقة، وهو ترس للائذين به.","30:6":"لا تضف على كلامه لئلا يوبخك فتصبح كاذبا.","30:7":"أمرين أطلب منك، فلا تحرمني منهما قبل أن أموت:","30:8":"أبعد عني الباطل وكلام الزور، ولا تجعل الفقر أو الغنى من نصيبي. لكن أعطني كفافي من الطعام،","30:9":"لئلا أشبع فأجحدك قائلا: من هو الرب؟ أو أفتقر فأسرق وألطخ اسم إلهي بالعار.","30:10":"لا تشك عبدا إلى سيده، لئلا يلعنك وتكون قد أثمت في حقه.","30:11":"رب جيل يشتم أباه ولا يبارك أمه.","30:12":"رب جيل نقي في عيني نفسه، وهو لم يتطهر بعد من رجاسته.","30:13":"رب جيل: لشد ما هو متشامخ العيون ومتعالي النظرات.","30:14":"رب جيل أسنانه مرهفة كالسيوف، وأنيابه حادة كالسكاكين، ليفترس المساكين في الأرض والبائسين من بين أبناء البشر.","30:15":"للعلقة بنتان هاتفتان: هات، هات. ثلاثة أشياء لا تشبع قط، والرابعة لا تقول كفى:","30:16":"الهاوية، والرحم العقيم، وأرض لا ترتوي من الماء، والنار التي لا تقول أبدا كفى.","30:17":"العين الساخرة بالأب، والتي تحتقر طاعة أمها، تقتلعها غربان الوادي، وتلتهمها فراخ النسور.","30:18":"ثلاثة أشياء أعجب من أن أستوعبها، وأربعة لا أعرفها:","30:19":"سبيل النسر في السماء، ودرب الحية على الصخر، وطريق السفينة في غمار البحر، وطريق رجل مع عذراء.","30:20":"هذا هو أسلوب المرأة العاهر ة: إنها تأثم وتستخف وتقول: لم أرتكب شرا!","30:21":"تحت عبء ثلاثة تقشعر الأرض، وتحت أربعة تنوء.","30:22":"تحت عبد إذا صار ملكا، وأحمق إذا شبع،","30:23":"وامرأة كريهة إذا تزوجت، وأمة إذا ورثت مولاتها.","30:24":"أربعة هي الصغرى في الأرض، ولكنها فائقة الحكمة:","30:25":"النمل طائفة ضعيفة، لكنه يخزن في الصيف قوته.","30:26":"الوبار طائفة لا قدرة لها، لكنها تنقر في الصخر بيوتها.","30:27":"والجراد لا ملك له، لكنه يتقدم في أسراب منظمة.","30:28":"والعنكبوت التي يمكن التقاطها باليد، ولكنها في قصور الملوك.","30:29":"ثلاثة جليلة في خطوها، وأربعة وقور في تحركها:","30:30":"الليث جبار الوحوش، الذي لا يتراجع أمام أحد،","30:31":"والطاووس المختال، والتيس، والملك في طليعة جيشه.","30:32":"إن انتابك الحمق فاغتررت بنفسك، أو شرعت في تدبير المكائد، فأطبق يدك على فمك.","30:33":"فكما أن مخض الحليب يخرج زبدة، والضغط على الأنف يجعله ينزف دما، فإن إثارة الغضب تولد الخصام.","31:1":"هذه أقوال لموئيل ملك مسا التي تلقنها من أمه:","31:2":"ماذا ياابني ياابن أحشائي، ياابن نذوري؟","31:3":"لا تنفق قوتك على النساء، ولا تستسلم لمن يهلكن الملوك.","31:4":"ليس للملوك يالموئيل، ليس للملوك أن يدمنوا الخمر، ولا للعظماء أن يجرعوا المسكر.","31:5":"لئلا يسكروا فينسوا الشريعة، ويجوروا على حقوق البائسين.","31:6":"أعطوا المسكر للهالك، والخمر لذوي النفوس التعسة،","31:7":"فيثملوا وينسوا فقرهم، ولا يذكروا بؤسهم بعد.","31:8":"افتح فمك مدافعا عن الأخرس، وفي دعوى كل منبوذ.","31:9":"افتح فمك قاضيا بالعدل، ودافع عن حقوق الفقراء والمحتاجين.","31:10":"من يعثر على المرأة الفاضلة؟ إن قيمتها تفوق اللآليء.","31:11":"بها يثق قلب زوجها فلا يحتاج إلى ما هو نفيس.","31:12":"تسبغ عليه الخير دون الشر كل أيام حياتها.","31:13":"تلتمس صوفا وكتانا وتشتغل بيدين راضيتين،","31:14":"فتكون كسفن التاجر التي تجلب طعامها من بلاد نائية.","31:15":"تنهض والليل ما برح مخيما، لتعد طعاما لأهل بيتها، وتدبر أعمال جواريها","31:16":"تتفحص حقلا وتشتريه، ومن مكسب يديها تغرس كرما","31:17":"تنطق حقويها بالقوة وتشدد ذراعيها.","31:18":"وتدرك أن تجارتها رابحة، ولا ينطفيء سراجها في الليل.","31:19":"تقبض بيديها على المغزل وتمسك كفاها بالفلكة.","31:20":"تبسط كفيها للفقير وتمد يديها لإغاثة البائس.","31:21":"لا تخشى على أهل بيتها من الثلج، لأن جميعهم يرتدون الحلل القرمزية.","31:22":"تصنع لنفسها أغطية موشاة، وثيابها محاكة من كتان وأرجوان.","31:23":"زوجها معروف في مجالس بوابات المدينة، حيث يجلس بين وجهاء البلاد.","31:24":"تصنع أقمصة كتانية وتبيعها، وتزود التاجر الكنعاني بمناطق.","31:25":"كساؤها العزة والشرف، وتبتهج بالأيام المقبلة.","31:26":"ينطق فمها بالحكمة، وفي لسانها سنة المعروف.","31:27":"ترعى بعناية شؤون أهل بيتها، ولا تأكل خبز الكسل.","31:28":"يقوم أبناؤها ويغبطونها، ويطريها زوجها أيضا قائلا:","31:29":"«نساء كثيرات قمن بأعمال جليلة، ولكنك تفوقت عليهن جميعا».","31:30":"الحسن غش والجمال باطل، أما المرأة المتقية الرب فهي التي تمدح.","31:31":"أعطوها من ثمر يديها، ولتكن أعمالها مصدر الثناء عليها."};
